export function RouteGuard({
  label = "{{label}}",
  requirement = "{{requirement}}",
  blocked = {{blocked}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430" }}>
      <a
        href="#"
        aria-disabled={blocked ? "true" : undefined}
        tabIndex={blocked ? -1 : undefined}
        style={{ display: "inline-flex", alignItems: "center", gap: 6, textDecoration: "none", color: "#241430", padding: "8px 10px", borderRadius: 8, opacity: blocked ? .45 : 1, pointerEvents: blocked ? "none" : "auto" }}
      >
        <span aria-hidden="true" style={{ width: 10, height: 8, border: "2px solid currentColor", borderRadius: 2 }} />
        {label}
      </a>
      {blocked ? (
        <span style={{ fontSize: 12, padding: "3px 9px", borderRadius: 999, background: "rgba(36,20,48,.08)", color: "#241430" }}>Blocked &middot; requires {requirement}</span>
      ) : (
        <span style={{ fontSize: 12, padding: "3px 9px", borderRadius: 999, background: "rgba(168,230,193,.5)", color: "#1c6b3c" }}>Allowed</span>
      )}
    </div>
  );
}
